import { useState } from 'react';
import { adminLogin } from '../apis/kycApi';

export default function Login({ onLogin }) {
  const [email, setEmail]       = useState('');
  const [password, setPassword] = useState('');
  const [showPw, setShowPw]     = useState(false);
  const [error, setError]       = useState('');
  const [loading, setLoading]   = useState(false);
  const [shake, setShake]       = useState(false);
  const [mode, setMode]         = useState('api');

  const DEMO = { email: 'admin@payo.com', password: 'Admin@123' };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    try {
      if (mode === 'demo') {
        await new Promise(r => setTimeout(r, 800));
        if (email === DEMO.email && password === DEMO.password) {
          localStorage.setItem('payo_admin_token', 'demo-token');
          onLogin({ name: 'Admin User', role: 'Super Admin', email });
        } else {
          throw new Error('Invalid demo credentials. Use admin@payo.com / Admin@123');
        }
      } else {
        // Real admin login → POST /api/admin/auth/login
        const res = await adminLogin(email, password);
        const token = res.data?.token || res.data?.accessToken;
        if (!token) throw new Error('No token received from server');
        localStorage.setItem('payo_admin_token', token);
        const adminName = res.data?.admin?.name || res.data?.name || 'Admin User';
        const adminRole = res.data?.admin?.role || res.data?.role || 'Admin';
        onLogin({ name: adminName, role: adminRole, email, token });
      }
    } catch (err) {
      setLoading(false);
      const msg = err.response?.data?.message || err.message || 'Login failed. Please try again.';
      setError(msg);
      setShake(true);
      setTimeout(() => setShake(false), 600);
    }
  };

  const fillDemo = () => { setEmail(DEMO.email); setPassword(DEMO.password); setMode('demo'); setError(''); };

  return (
    <div style={{ minHeight:'100vh', background:'linear-gradient(135deg,#0A0A0A 0%,#0D1B3E 50%,#0A0A0A 100%)', display:'flex', alignItems:'center', justifyContent:'center', padding:20, position:'relative', overflow:'hidden' }}>
      <div style={{ position:'absolute', width:400, height:400, borderRadius:'50%', background:'#8B5CF6', opacity:0.06, filter:'blur(80px)', top:-100, left:-100, pointerEvents:'none' }}/>
      <div style={{ position:'absolute', width:400, height:400, borderRadius:'50%', background:'#06B6D4', opacity:0.06, filter:'blur(80px)', bottom:-100, right:-100, pointerEvents:'none' }}/>

      <div style={{ width:'100%', maxWidth:420, position:'relative', zIndex:1 }}>

        {/* Logo */}
        <div style={{ display:'flex', justifyContent:'center', marginBottom:28 }}>
          <img src={process.env.PUBLIC_URL + "/images/payo-icon-logo-removebg-preview.png"} alt="PayO"
            style={{ width:110, height:110, objectFit:'contain', borderRadius:22, display:'block' }}
            onError={e => { e.target.style.display='none'; }}/>
        </div>

        {/* Mode toggle */}
        <div style={{ display:'flex', background:'rgba(255,255,255,0.06)', borderRadius:12, padding:4, marginBottom:18, border:'1px solid rgba(255,255,255,0.08)' }}>
          {[['api','🔌 Live API'],['demo','🎭 Demo Mode']].map(([m,l])=>(
            <button key={m} onClick={()=>{setMode(m);setError('');}} style={{
              flex:1, padding:'9px', border:'none', borderRadius:9,
              background: mode===m ? 'rgba(37,99,235,0.8)' : 'transparent',
              color: mode===m ? '#fff' : 'rgba(255,255,255,0.4)',
              fontSize:13, fontWeight:600, cursor:'pointer',
              fontFamily:"'Inter',sans-serif", transition:'all 0.2s',
            }}>{l}</button>
          ))}
        </div>

        {/* Info banner */}
        {mode === 'api' ? (
          <div style={{ background:'rgba(37,99,235,0.12)', border:'1px solid rgba(37,99,235,0.25)', borderRadius:10, padding:'10px 14px', marginBottom:18, fontSize:12, color:'rgba(255,255,255,0.55)', lineHeight:1.6 }}>
            🔌 Admin login via <code style={{color:'#60A5FA'}}>POST /api/admin/auth/login</code><br/>
            Make sure your backend is running on <code style={{color:'#60A5FA'}}>localhost:3001</code>
          </div>
        ) : (
          <div style={{ background:'rgba(245,158,11,0.12)', border:'1px solid rgba(245,158,11,0.25)', borderRadius:10, padding:'10px 14px', marginBottom:18, fontSize:12, color:'rgba(255,255,255,0.55)', lineHeight:1.5 }}>
            🎭 Demo mode — no backend needed. All data is mock data.
          </div>
        )}

        {/* Card */}
        <div style={{ background:'rgba(255,255,255,0.04)', border:'1px solid rgba(255,255,255,0.09)', borderRadius:20, padding:'32px 32px 28px', backdropFilter:'blur(20px)', boxShadow:'0 24px 80px rgba(0,0,0,0.5)', animation:shake?'shake 0.5s ease':'none' }}>
          <style>{`
            @keyframes shake { 0%,100%{transform:translateX(0)} 20%{transform:translateX(-8px)} 40%{transform:translateX(8px)} 60%{transform:translateX(-5px)} 80%{transform:translateX(5px)} }
            @keyframes spin { to{transform:rotate(360deg)} }
            .li{width:100%;padding:11px 12px;background:rgba(255,255,255,0.06);border:1.5px solid rgba(255,255,255,0.1);border-radius:10px;font-size:14px;color:#fff;outline:none;font-family:'Inter',sans-serif;transition:border-color 0.2s;}
            .li::placeholder{color:rgba(255,255,255,0.28);}
            .li:focus{border-color:#3B82F6;background:rgba(255,255,255,0.09);}
            .li.err{border-color:#EF4444;}
          `}</style>

          <h2 style={{ fontFamily:"'Space Grotesk',sans-serif", fontSize:20, fontWeight:700, color:'#fff', marginBottom:5, letterSpacing:'-0.3px' }}>Welcome back</h2>
          <p style={{ fontSize:13, color:'rgba(255,255,255,0.4)', marginBottom:24 }}>Sign in to your admin account</p>

          <form onSubmit={handleSubmit}>
            <div style={{ marginBottom:14 }}>
              <label style={{ display:'block', fontSize:11, fontWeight:600, color:'rgba(255,255,255,0.4)', textTransform:'uppercase', letterSpacing:'0.8px', marginBottom:6 }}>Email</label>
              <input className={`li${error?' err':''}`} type="email" placeholder="admin@payo.com"
                value={email} onChange={e=>{setEmail(e.target.value);setError('');}} required/>
            </div>

            <div style={{ marginBottom:22 }}>
              <label style={{ display:'block', fontSize:11, fontWeight:600, color:'rgba(255,255,255,0.4)', textTransform:'uppercase', letterSpacing:'0.8px', marginBottom:6 }}>Password</label>
              <div style={{ position:'relative' }}>
                <input className={`li${error?' err':''}`} type={showPw?'text':'password'} placeholder="Enter your password"
                  value={password} onChange={e=>{setPassword(e.target.value);setError('');}} required style={{ paddingRight:44 }}/>
                <button type="button" onClick={()=>setShowPw(p=>!p)} style={{ position:'absolute', right:12, top:'50%', transform:'translateY(-50%)', background:'none', border:'none', cursor:'pointer', color:'rgba(255,255,255,0.35)', fontSize:15, padding:0 }}>
                  {showPw?'🙈':'👁️'}
                </button>
              </div>
            </div>

            {error && (
              <div style={{ background:'rgba(239,68,68,0.14)', border:'1px solid rgba(239,68,68,0.3)', borderRadius:9, padding:'10px 13px', marginBottom:16, fontSize:13, color:'#FCA5A5', display:'flex', alignItems:'center', gap:8 }}>
                ⚠️ {error}
              </div>
            )}

            <button type="submit" disabled={loading} style={{
              width:'100%', padding:'13px',
              background:loading?'rgba(37,99,235,0.4)':'linear-gradient(135deg,#2563EB,#3B82F6)',
              border:'none', borderRadius:10, color:'#fff', fontSize:14, fontWeight:600,
              cursor:loading?'not-allowed':'pointer', fontFamily:"'Inter',sans-serif",
              boxShadow:'0 4px 20px rgba(37,99,235,0.35)', transition:'all 0.2s',
              display:'flex', alignItems:'center', justifyContent:'center', gap:8,
            }}>
              {loading
                ? <><span style={{ width:16, height:16, border:'2px solid rgba(255,255,255,0.3)', borderTopColor:'#fff', borderRadius:'50%', animation:'spin 0.7s linear infinite', display:'inline-block' }}/> Signing in...</>
                : mode==='api' ? 'Sign In →' : 'Sign In (Demo) →'
              }
            </button>
          </form>

          <div style={{ marginTop:18, textAlign:'center' }}>
            <button onClick={fillDemo} style={{ background:'none', border:'none', cursor:'pointer', fontSize:12.5, color:'rgba(255,255,255,0.3)', fontFamily:"'Inter',sans-serif", textDecoration:'underline', textUnderlineOffset:3 }}>
              Fill demo credentials
            </button>
          </div>
        </div>

        {/* Creds box */}
        <div style={{ marginTop:16, background:'rgba(255,255,255,0.04)', border:'1px solid rgba(255,255,255,0.07)', borderRadius:12, padding:'14px 18px', display:'flex', justifyContent:'space-between', alignItems:'center' }}>
          <div>
            <div style={{ fontSize:10.5, color:'rgba(255,255,255,0.28)', fontWeight:600, textTransform:'uppercase', letterSpacing:'0.8px', marginBottom:6 }}>
              {mode==='api'?'Admin Credentials':'Demo Credentials'}
            </div>
            <div style={{ fontSize:12.5, color:'rgba(255,255,255,0.5)' }}>📧 {DEMO.email}</div>
            <div style={{ fontSize:12.5, color:'rgba(255,255,255,0.5)', marginTop:2 }}>🔑 {DEMO.password}</div>
            {mode==='api'&&<div style={{ fontSize:11, color:'rgba(255,255,255,0.3)', marginTop:4 }}>🌐 localhost:3001 → /api/admin/auth/login</div>}
          </div>
          <button onClick={fillDemo} style={{ background:'rgba(37,99,235,0.2)', border:'1px solid rgba(37,99,235,0.35)', borderRadius:8, padding:'7px 14px', color:'#93C5FD', fontSize:12, fontWeight:600, cursor:'pointer', fontFamily:"'Inter',sans-serif" }}>
            Fill
          </button>
        </div>
      </div>
    </div>
  );
}
